mapper.select:
SELECT  FROM seal.recipient recipient
 WHERE recipient.organization_unit_id = #{organizationId}
   AND recipient.email_lookup_hmac = #{emailLookupHmac}
   AND recipient.recipient_status = 'ACTIVE'

   AND recipient.recipient_id <> #{excludedRecipientId}

 LIMIT 1


SELECT  FROM seal.recipient recipient
JOIN visible_scope scope ON scope.organization_unit_id = recipient.organization_unit_id

    recipient.email_lookup_hmac = #{emailLookupHmac}

        AND POSITION(LOWER(#{collectionBasis}) IN LOWER(recipient.collection_basis)) > 0

    AND recipient.recipient_status = #{status}

ORDER BY recipient.created_at DESC, recipient.recipient_id
LIMIT #{limit} OFFSET #{offset}
